-- 19 contract types (Other is the fallback)
INSERT INTO contract_types (field_set_id, key, label, description, is_fallback, position)
SELECT (SELECT id FROM field_sets WHERE name = 'contract_fields' AND version = 1), v.key, v.label, v.description, v.is_fallback, v.position
FROM (VALUES
    ('nda', 'NDA', 'Non-disclosure or confidentiality agreement whose main purpose is protecting information disclosed between the parties, mutual or one-way.', false, 1),
    ('msa', 'MSA', 'Master or framework agreement setting general terms for future services or purchases; individual engagements are made by SOWs, work orders or purchase orders under it.', false, 2),
    ('sow', 'SOW', 'Statement of work, work order or project schedule, usually under a master agreement, describing one project''s scope, deliverables, milestones and fees.', false, 3),
    ('saas', 'SaaS', 'Subscription to hosted software or cloud services: subscription fees, users or seats, uptime and service levels, customer data, support.', false, 4),
    ('employment', 'Employment', 'Employment contract or offer letter between an employer and an individual employee: position, salary, hours, leave, notice.', false, 5),
    ('contractor', 'Contractor', 'Independent contractor or consulting agreement with an individual or small business providing personal services, expressly not employment.', false, 6),
    ('goods_purchase', 'Goods Purchase', 'Purchase of goods: purchase order, order form or sale-of-goods terms with line items, delivery, and transfer of title and risk.', false, 7),
    ('supply_distribution', 'Supply & Distribution', 'Ongoing supply, distribution, reseller or agency arrangement: products, territory, forecasts, minimum orders, rebates.', false, 8),
    ('property_lease', 'Property Lease', 'Lease or licence of real property (office, retail or industrial premises): premises, rent, outgoings, make good.', false, 9),
    ('equipment_lease', 'Equipment Lease', 'Lease, hire or rental of equipment, vehicles or machinery: lease payments, residual value, purchase option, return conditions.', false, 10),
    ('loan', 'Loan', 'Loan, credit or facility agreement: facility limit, interest, repayment, security, financial covenants, events of default.', false, 11),
    ('ip_license', 'IP License', 'Licence of patents, trade marks, copyright, software or technology for fees or royalties (not a hosted SaaS subscription).', false, 12),
    ('jv_partnership', 'JV & Partnership', 'Joint venture, partnership, shareholders'' or strategic alliance agreement: contributions, ownership, governance, profit sharing, exit.', false, 13),
    ('share_asset_purchase', 'Share-Asset Purchase', 'Sale and purchase of shares or of a business or its assets: purchase price, conditions precedent, completion, warranties, indemnities.', false, 14),
    ('franchise', 'Franchise', 'Franchise agreement granting the right to run a business under the franchisor''s brand and system: franchise fees, royalties, territory.', false, 15),
    ('construction', 'Construction', 'Construction, building or engineering works contract: contract sum, progress claims, practical completion, defects liability, variations.', false, 16),
    ('dpa', 'DPA', 'Data processing agreement or addendum setting how a processor handles personal data on behalf of a controller.', false, 17),
    ('amendment', 'Amendment', 'Amendment, variation, addendum or change order that modifies an existing agreement rather than standing alone.', false, 18),
    ('other', 'Other', 'Fallback for contracts that match none of the types above.', true, 19)
) AS v (key, label, description, is_fallback, position);

